{"file_path": "graph.yml", "content": "id: authored-workshop
version: '1'
entry: analyze
nodes:
  - id: analyze
    kind: act
    parameters:
      workshop: analyze
      arguments:
        SCALE: { from: strategy, name: scale }
  - id: read-analysis
    kind: act
    parameters: { observes: analysis }
  - id: judge
    kind: judge
    parameters: { rules: [sum-valid] }
  - id: blocked
    kind: wait
    parameters: { blocker: hard-blocker }
edges:
  - { from: analyze, to: read-analysis }
  - { from: read-analysis, to: judge }
"}

{"file_path": "rules/sum-valid.yml", "content": "id: sum-valid
version: '1'
title: The scaled sum matches the known input
requires: [{ type: scaled_sum }]
subject: { type: scaled_sum }
predicate: { op: eq, threshold: 42, unit: count }
"}
